/* @lc app=leetcode id=994 lang=kotlin */ class Solution { fun set(g: Array<IntArray>, p: IntArray) { g[p[0]][p[1]] = 2 } fun orangesRotting(grid: Array<IntArray>): Int = generateSequence(grid.indices.flatMap { i -> grid[0].indices.filter { grid[i][it] == 2 }.map { intArrayOf(i, it) } }) { f -> f.flatMap { p -> listOf(intArrayOf(1, 0), intArrayOf(-1, 0), intArrayOf(0, 1), intArrayOf(0, -1)).map { intArrayOf(p[0] + it[0], p[1] + it[1]) } }.filter { it[0] in grid.indices && it[1] in grid[0].indices && grid[it[0]][it[1]] == 1 }.distinctBy { it[0] * grid[0].size + it[1] }.onEach { set(grid, it) }.takeIf { it.isNotEmpty() } }.count().let { L -> if (grid.any { r -> 1 in r }) -1 else maxOf(0, L - 1) } }